{"content":"class StackUnderflowError(Exception):
    """Raised when an operation needs more items than the stack contains."""


def evaluate(input_data):
    """Evaluate Forth source lines and return the stack, bottom item first."""
    stack = []
    words = {word: (word,) for word in ("+", "-", "*", "/", "dup", "drop", "swap", "over")}
    tokens = " ".join(input_data).lower().split()

    def is_number(token):
        return token.isascii() and token.isdigit()

    def resolve(token):
        if is_number(token):
            return (int(token),)
        if token not in words:
            raise ValueError(f"undefined operation: {token}")
        return words[token]

    def execute(instructions):
        for instruction in instructions:
            if isinstance(instruction, int):
                stack.append(instruction)
                continue

            needed = 1 if instruction in ("dup", "drop") else 2
            if len(stack) < needed:
                raise StackUnderflowError("Insufficient number of items in stack")

            if instruction == "dup":
                stack.append(stack[-1])
            elif instruction == "drop":
                stack.pop()
            elif instruction == "swap":
                stack[-2], stack[-1] = stack[-1], stack[-2]
            elif instruction == "over":
                stack.append(stack[-2])
            else:
                left, right = stack[-2:]
                if instruction == "+":
                    result = left + right
                elif instruction == "-":
                    result = left - right
                elif instruction == "*":
                    result = left * right
                else:
                    if right == 0:
                        raise ZeroDivisionError("divide by zero")
                    # Truncate toward zero without converting to floating point.
                    result = abs(left) // abs(right)
                    if (left < 0) != (right < 0):
                        result = -result
                stack[-2:] = [result]

    index = 0
    while index < len(tokens):
        token = tokens[index]
        index += 1
        if token != ":":
            execute(resolve(token))
            continue

        if index == len(tokens):
            raise ValueError("illegal operation: missing word name")
        name = tokens[index]
        index += 1
        if is_number(name) or name in (":", ";"):
            raise ValueError(f"illegal operation: invalid word name {name}")

        definition = []
        while index < len(tokens) and tokens[index] != ";":
            # Capture the current meaning, so later redefinitions do not
            # change this word (including when a word redefines itself).
            definition.extend(resolve(tokens[index]))
            index += 1
        if index == len(tokens):
            raise ValueError("illegal operation: missing ';' after definition")
        words[name] = tuple(definition)
        index += 1

    return stack
