{"content":"import unittest

from forth import StackUnderflowError, evaluate


class ForthTests(unittest.TestCase):
    def test_numbers_and_empty_input(self):
        self.assertEqual(evaluate([]), [])
        self.assertEqual(evaluate(["1 2", "32768 0004"]), [1, 2, 32768, 4])

    def test_arithmetic(self):
        for source, expected in (
            ("1 2 +", [3]),
            ("3 5 -", [-2]),
            ("2 3 *", [6]),
            ("8 3 /", [2]),
            ("1 2 3 * +", [7]),
            ("0 7 - 3 /", [-2]),
            ("7 0 3 - /", [-2]),
            ("0 7 - 0 3 - /", [2]),
        ):
            with self.subTest(source=source):
                self.assertEqual(evaluate([source]), expected)

    def test_division_preserves_large_integer_precision(self):
        number = 10 ** 100 + 2
        self.assertEqual(evaluate([f"{number} 3 /"]), [number // 3])

    def test_stack_operations_are_case_insensitive(self):
        for source, expected in (
            ("1 DuP", [1, 1]),
            ("1 2 DROP", [1]),
            ("1 2 sWaP", [2, 1]),
            ("1 2 OVER", [1, 2, 1]),
        ):
            with self.subTest(source=source):
                self.assertEqual(evaluate([source]), expected)

    def test_underflow(self):
        for word, required in (("+", 2), ("-", 2), ("*", 2), ("/", 2),
                               ("dup", 1), ("drop", 1), ("swap", 2), ("over", 2)):
            for count in range(required):
                with self.subTest(word=word, count=count):
                    with self.assertRaisesRegex(StackUnderflowError, "Insufficient"):
                        evaluate(["1 " * count + word])

    def test_division_by_zero(self):
        with self.assertRaisesRegex(ZeroDivisionError, "divide by zero"):
            evaluate(["1 0 /"])

    def test_definitions(self):
        self.assertEqual(evaluate([": square dup * ;", "3 SQUARE 4 square"]), [9, 16])
        self.assertEqual(evaluate([": twice", "dup + ; 5 twice"]), [10])
        self.assertEqual(evaluate([": a 1 ; : b a a + ; b"]), [2])

    def test_definitions_capture_existing_meaning(self):
        self.assertEqual(evaluate([": foo 5 ; : bar foo ; : foo 6 ; bar foo"]), [5, 6])
        self.assertEqual(evaluate([": foo 10 ; : foo foo 1 + ; foo"]), [11])
        self.assertEqual(evaluate([": add + ; : + * ; 2 3 add 2 3 +"]), [5, 6])
        self.assertEqual(evaluate([": DUP 2 ; dup"]), [2])

    def test_word_names_can_contain_digits_and_symbols(self):
        self.assertEqual(evaluate([": a1!? 3 ; A1!?"]), [3])
        self.assertEqual(evaluate([": -1 7 ; -1"]), [7])
        self.assertEqual(evaluate([": ١ 8 ; ١"]), [8])

    def test_invalid_definitions(self):
        for source in (": 1 2 ;", ": 001 2 ;", ":", ": ;", ": : 1 ;", ": foo 1"):
            with self.subTest(source=source):
                with self.assertRaisesRegex(ValueError, "illegal operation"):
                    evaluate([source])

    def test_unknown_words(self):
        for source in ("unknown", ": foo unknown ;", ": foo foo ;", "1 ;", "١", "-1"):
            with self.subTest(source=source):
                with self.assertRaisesRegex(ValueError, "undefined operation"):
                    evaluate([source])

    def test_empty_definition(self):
        self.assertEqual(evaluate([": noop ; 1 noop"]), [1])

    def test_evaluations_do_not_share_state(self):
        self.assertEqual(evaluate([": foo 1 ; foo"]), [1])
        self.assertEqual(evaluate([]), [])
        with self.assertRaisesRegex(ValueError, "undefined operation"):
            evaluate(["foo"])


if __name__ == "__main__":
    unittest.main()
